public class PointTester2 {
	public static void main(String[] args) {
		Point2 point = new Point2();
		point.setX(7);
		point.setY(2);
		System.out.println("El-koordinat taba' al-noqta: (" + point.getX() + ", " + point.getY() + ")") ;
		System.out.println("Masafa al-noqta min al-asl = " + point.distanceFromOrigin());
	}
}
class Point2 {
	//Khatwa 1: a'lan al-mutaghayyirat al-instansiyya
	private int x;
	private int y;
	//Khatwa 2: a'lan al-tariqa li-hisab wa 'iadat masaafa al-noqta min al-asl
	public double distanceFromOrigin() {
		return Math.sqrt(x * x + y * y);
	}
	//Khatwa 3: ta'reef wasail al-tahdeed wa al-istikhraj li-ee'niyat x li al-noqta
	public void setX(int newX) {
		x = newX;
	}
	public int getX() {
		return x;
	}
	//Khatwa 4: ta'reef wasail al-tahdeed wa al-istikhraj li-ee'niyat y li al-noqta
	public void setY(int newY) {
		y = newY;
	}
	public int getY() {
		return y;
	}
}
